function Frame137() {
  return (
    <div className="bg-white relative rounded-[15px] shrink-0 w-full">
      <div className="flex flex-row items-center justify-center size-full">
        <div className="content-stretch flex items-center justify-center p-[20px] relative size-full">
          <ol className="[word-break:break-word] block font-['Open_Sans:Regular','Noto_Sans:Regular','Noto_Sans_Math:Regular','Noto_Sans_Symbols:Regular','Noto_Sans_Symbols2:Regular',sans-serif] font-normal leading-[0] list-decimal relative shrink-0 text-[16px] text-black tracking-[0.64px] w-[1035px]" start="1" style={{ fontVariationSettings: '"wdth" 100' }}>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"How do you currently keep track of lists — recipes, trips, to-dos, anything? Walk me through it."`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"What app or method do you use for that? What made you pick it?"`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"What's frustrating about it? Where does it fall short for you?"`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"Let's say you're planning to cook something healthy this week. Maybe you want a diet plan or recipe ideas. You've got this app open. What's the first thing you'd do?" (watch: do they head to search unprompted, or browse the homepage first?)`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"Say you're trying to lose weight and want to see if someone's already made a list of what to eat or what actions to take. Everything you see is made by other people — how would you go about finding that?" (this is your search + smart-results test — let them describe what they see on screen as they go, don't lead them to the two columns)`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"You found something useful. It belongs to someone else right now — what would you do if you wanted it to be yours, something you could edit?" (don't say "duplicate" and see if they find their own words for it, then find the button)`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"Before you tap that, what do you think happens next?" (catches expectation vs. reality, ask this right before they click)`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"Okay, you've made it yours now. Where do you think it went? Where would you look for it later?" (this is your public→personal psychology question — very good instinct putting it here)`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"Change something in that list to make it actually match what you'd eat or do. How would you do that?"`}</span>
            </li>
            <li className="mb-0 ms-[24px]">
              <span className="leading-[1.6]">{`"would you recomenned this app to somebody ? why or why not ? "`}</span>
            </li>
            <li className="ms-[24px]">
              <span className="leading-[1.6]">{`"Was there a moment where you weren't sure what would happen, or it did something you didn't expect?"`}</span>
            </li>
          </ol>
        </div>
      </div>
    </div>
  );
}

